<?php
require __DIR__.'/bootstrap.php';
requireAuth();
if(!canViewAudit()){http_response_code(403);exit('No autorizado.');}
$error='';$items=[];
try{$pdo=db();$items=$pdo->query('SELECT action,entity_type,created_at FROM admin_audit_log ORDER BY created_at DESC LIMIT 300')->fetchAll();}catch(Throwable $e){error_log('InYou auditoria: '.$e->getMessage());$error='No se pudo cargar la auditoría.';}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auditoría · InYou</title><link rel="stylesheet" href="/admin/style.css"><style>.wrap{max-width:1100px;margin:auto}.panel{background:#fff;border:1px solid #e7e5df;border-radius:12px;padding:22px;margin:20px 0}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #eee;text-align:left}.muted{color:#777}</style></head><body class="dashboard"><?php adminSidebar('audit');?><main class="content"><div class="wrap"><header><div>Hola, <?=h($_SESSION['admin_name']??'Administrador')?></div><form method="post" action="/admin/logout.php"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button class="signout">Cerrar sesión</button></form></header><div class="eyebrow">SEGURIDAD</div><h1>Auditoría</h1><p>Registro de cambios realizados desde el panel administrativo.</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><section class="panel"><div style="overflow:auto"><table class="table"><thead><tr><th>Fecha</th><th>Acción</th><th>Entidad</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=h($i['created_at'])?></td><td><?=h($i['action'])?></td><td><?=h($i['entity_type'])?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="3" class="muted">Todavía no hay actividad registrada.</td></tr><?php endif;?></tbody></table></div></section></div></main></body></html>